 private function verified(array$identity,NativePortalIdentity$service,int$issuer):void{if($service->current($this->ci->session,$issuer)!==$identity)throw new DomainException('company_portal_sales_unavailable');$b=$identity['binding'];$rows=IssuerStorage::query($this->ci->db,'SELECT email_verified_at FROM '.db_prefix().'contacts WHERE id=? AND userid=?',[$b['contact_id'],$b['client_id']])->result_array();if(count($rows)!==1||$rows[0]['email_verified_at']===null)throw new DomainException('company_portal_sales_unavailable');}
